schema.schema:
{
  "$defs": {
    "Disagreement": {
      "additionalProperties": false,
      "description": "One field on which a slice's matched leads materially disagree.\n\nRecorded by the `/spec:plan` propose agent alongside a `divergence`\nflag. The CLI never decides materiality — it only checks structural\nconsistency: a flagged slice records at least one disagreement, and\neach disagreement names at least two distinct source values.",
      "properties": {
        "field": {
          "description": "The aspect the sources disagree on (a free-form label, e.g.\n`password-min-length`).",
          "type": "string"
        },
        "values": {
          "description": "The per-source values that disagree on `field`. A genuine\ndisagreement records at least two distinct source values.",
          "items": {
            "$ref": "#/$defs/DisagreementValue"
          },
          "type": "array"
        }
      },
      "required": [
        "field",
        "values"
      ],
      "type": "object"
    },
    "DisagreementValue": {
      "additionalProperties": false,
      "description": "One source's value for a [`Disagreement`] field.",
      "properties": {
        "source": {
          "description": "Source key contributing this value (a `plan.yaml.sources.<key>`).",
          "type": "string"
        },
        "value": {
          "description": "The value this source surfaced for the disagreeing field.",
          "type": "string"
        }
      },
      "required": [
        "source",
        "value"
      ],
      "type": "object"
    },
    "Divergence": {
      "description": "Slice-level reconciliation outcome.\n\nClosed `none | likely | accepted | rejected` taxonomy on\n`plan.yaml.slices[].divergence`, written only by `specify plan\namend`.",
      "oneOf": [
        {
          "const": "none",
          "description": "No divergence — the implicit default for slice records (absent\non disk) and the explicit first value of the journal\n`plan.amend.divergence` `from` field on the first transition.",
          "type": "string"
        },
        {
          "const": "likely",
          "description": "Staged by the `/spec:plan` agent after the reconcile write, via\n`specify plan amend --divergence likely`, on\nmaterially-disagreeing lead synopses.",
          "type": "string"
        },
        {
          "const": "accepted",
          "description": "Operator-stamped at Gate 1 — divergence acknowledged and\naccepted into the plan.",
          "type": "string"
        },
        {
          "const": "rejected",
          "description": "Operator-stamped at Gate 1 — divergence rejected; the plan\nmust be re-proposed before Gate 1 review.",
          "type": "string"
        }
      ]
    },
    "GateProse": {
      "additionalProperties": false,
      "description": "Gate 1 review prose riding a [`ProposalResponse`]: section bodies\nonly — the orchestrator owns every deterministic frame (`# Change —\n<name>`, `# Discovery — <name>`, the `##` headings).",
      "properties": {
        "change": {
          "description": "The `change.md` operator brief body rendered below the\ndeterministic `# Change — <name>` heading: intent, scope, and\nthe Gate 1 review sections the skill flow authored by hand\n(`## Tentative merges`, `## Cross-cutting leads`, `## Likely\ndivergences` when applicable).",
          "type": "string"
        },
        "discovery-source-inventory": {
          "description": "The `discovery.md` `## Source inventory` section body — one row\nper bound source under `plan.yaml.sources.<key>`: key, adapter,\npath or value. Body only, no heading.",
          "type": "string"
        },
        "discovery-summary": {
          "description": "The `discovery.md` `## Summary` section body — one-line counts\n(`Sources: N. Leads: M.`). Body only, no heading.",
          "type": "string"
        }
      },
      "required": [
        "change",
        "discovery-summary",
        "discovery-source-inventory"
      ],
      "type": "object"
    },
    "ProposalKind": {
      "description": "Reconciliation envelope kind.\n\nSerialises to the literal `\"request\"` / `\"response\"`.\n[`ProposalRequest`] always carries\n[`ProposalKind::Request`]; [`ProposalResponse`] always carries\n[`ProposalKind::Response`].",
      "oneOf": [
        {
          "const": "request",
          "description": "Lead catalog and project topology for the agent to group.",
          "type": "string"
        },
        {
          "const": "response",
          "description": "Agent-authored `slices[]` grouping.",
          "type": "string"
        }
      ]
    },
    "ResponseMember": {
      "additionalProperties": false,
      "description": "One matched catalog row referenced by a [`ResponseSlice`].",
      "properties": {
        "lead": {
          "description": "Discovery lead id; with `source`, must match a request\ncatalog row.",
          "type": "string"
        },
        "source": {
          "description": "Plan source binding key; must match a request catalog row.",
          "type": "string"
        }
      },
      "required": [
        "source",
        "lead"
      ],
      "type": "object"
    },
    "ResponseSlice": {
      "additionalProperties": false,
      "description": "One `slices[]` row in a [`ProposalResponse`]: one slice of work\ncarrying its matched `sources[]` inline and its explicit `name`.\n\nThere is no `scope` noun and no kernel fan-out grouping. A body of\nwork that targets more than one project\nis expressed as multiple ordinary slices (which may legally reference\nthe same lead) joined by `depends-on`; the agent's explicit `name`\ndisambiguates cross-source matches that carry differing slugs.",
      "properties": {
        "depends-on": {
          "description": "Slice names this row depends on. Empty stays off the wire.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "disagreements": {
          "description": "The per-field disagreeing values backing a `divergence` flag.\nRecommended non-empty (with ≥2 distinct source values each) when\n`divergence` is `likely`; the CLI advises on structural\nconsistency but never decides materiality and never blocks. Empty\nstays off the wire.",
          "items": {
            "$ref": "#/$defs/Disagreement"
          },
          "type": "array"
        },
        "divergence": {
          "anyOf": [
            {
              "$ref": "#/$defs/Divergence"
            },
            {
              "type": "null"
            }
          ],
          "description": "Agent-flagged slice-level divergence: `likely` when the matched\nleads materially disagree. Absent means no divergence. The kernel\ncarries it onto `plan.yaml.slices[].divergence`; the operator\nadjudicates `accepted` / `rejected` later via `specify plan amend\n--divergence`."
        },
        "name": {
          "description": "Explicit plan slice name (kebab-case). Required — with `scope`\ngone the agent names every slice directly, and the kernel writes\nit verbatim to `plan.yaml.slices[].name`.",
          "type": "string"
        },
        "project": {
          "description": "Project this slice binds to, chosen from the request's\n`projects[]`. Optional only when exactly one project exists, in\nwhich case the kernel auto-binds it.",
          "type": [
            "string",
            "null"
          ]
        },
        "rationale": {
          "description": "Optional cross-source-match rationale the agent renders into\n`change.md` for Gate 1. Agent-authored and kernel-ignored — it is\nnot echoed into the journal.",
          "type": [
            "string",
            "null"
          ]
        },
        "sources": {
          "description": "Matched catalog rows, each referenced by `{ source, lead }`\n(at most one per source). A lead may appear in more than one\nslice — that is fan-out.",
          "items": {
            "$ref": "#/$defs/ResponseMember"
          },
          "type": "array"
        }
      },
      "required": [
        "name",
        "sources"
      ],
      "type": "object"
    }
  },
  "$id": "https://github.com/augentic/specify/answers/proposal.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "Generated judgment-answer schema — generated from the Rust wire types by project::answers; do not edit. Validates the schema-gated answer to the plan-time lead-reconciliation judgment: the `kind: response` envelope the guest `plan author` orchestration consumes. The deterministic tail re-checks the envelope kind and runs the projection kernel.",
  "properties": {
    "gate": {
      "anyOf": [
        {
          "$ref": "#/$defs/GateProse"
        },
        {
          "type": "null"
        }
      ],
      "description": "Gate 1 review prose authored alongside the grouping.\nCanonically optional; the generated judgment-answer schema\nrequires it, and the collapsed `plan author` orchestration\npersists it into `change.md` / `discovery.md`. The projection\nkernel ignores it."
    },
    "kind": {
      "const": "response"
    },
    "slices": {
      "description": "The agent's slices, in response order — the kernel writes\n`plan.yaml.slices[]` in this order.",
      "items": {
        "$ref": "#/$defs/ResponseSlice"
      },
      "type": "array"
    },
    "version": {
      "description": "Schema version.",
      "format": "uint32",
      "minimum": 0,
      "type": "integer"
    }
  },
  "required": [
    "version",
    "kind",
    "slices",
    "gate"
  ],
  "title": "Specify plan reconciliation answer",
  "type": "object"
}

